SELECT "item", "warehouse", "lines", "on_hand", "sold", "weekly_demand", "proposed_qty", 'propose' AS "route", CASE WHEN "on_hand" IS NULL THEN '' ELSE CAST("on_hand" AS VARCHAR) END || ' on hand covers less than ' || CAST(:cover_target AS VARCHAR) || ' weeks of ' || CASE WHEN "weekly_demand" IS NULL THEN '' ELSE CAST("weekly_demand" AS VARCHAR) END || ' a week' AS "verdict_reason"
FROM (SELECT "t9"."item", "t9"."warehouse", "t9"."lines", "t9"."on_hand", "t15"."sold", "t15"."weekly_demand", CEIL(:order_up_to * "t15"."weekly_demand" - "t9"."on_hand") AS "proposed_qty"
        FROM (SELECT "t0"."item", "t0"."warehouse", "t0"."lines", "t8"."on_hand"
                FROM (SELECT "item", "warehouse", COUNT("line_no") AS "lines"
                        FROM "sales_line"
                        WHERE "sold_date" >= :as_of_minus_demand_period_weeks AND "sold_date" <= :as_of
                        GROUP BY "item", "warehouse") AS "t0"
                    LEFT JOIN (SELECT "t3"."item", "t3"."warehouse", COALESCE("t3"."quantity_on_hand", 0) AS "on_hand"
                        FROM (SELECT "t2"."item", "t2"."warehouse", "t2"."lines", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t2"."item" IS NULL THEN 'n' ELSE 'v' || CAST("t2"."item" AS VARCHAR) END AS "_ttrp_g_n7_0", CASE WHEN "t2"."warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("t2"."warehouse" AS VARCHAR) END AS "_ttrp_g_n7_1"
                                FROM (SELECT "item", "warehouse", COUNT("line_no") AS "lines"
                                        FROM "sales_line"
                                        WHERE "sold_date" >= :as_of_minus_demand_period_weeks AND "sold_date" <= :as_of
                                        GROUP BY "item", "warehouse") AS "t2"
                                    LEFT JOIN "inventory" ON "t2"."item" = "inventory"."item" AND "t2"."warehouse" = "inventory"."warehouse") AS "t3"
                            INNER JOIN (SELECT CASE WHEN "t5"."item" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."item" AS VARCHAR) END AS "_ttrp_g_n7_0", CASE WHEN "t5"."warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."warehouse" AS VARCHAR) END AS "_ttrp_g_n7_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n7"
                                FROM (SELECT "item", "warehouse", COUNT("line_no") AS "lines"
                                        FROM "sales_line"
                                        WHERE "sold_date" >= :as_of_minus_demand_period_weeks AND "sold_date" <= :as_of
                                        GROUP BY "item", "warehouse") AS "t5"
                                    LEFT JOIN "inventory" AS "inventory0" ON "t5"."item" = "inventory0"."item" AND "t5"."warehouse" = "inventory0"."warehouse"
                                GROUP BY CASE WHEN "t5"."item" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."item" AS VARCHAR) END, CASE WHEN "t5"."warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."warehouse" AS VARCHAR) END) AS "t7" ON "t3"."_ttrp_g_n7_0" = "t7"."_ttrp_g_n7_0" AND "t3"."_ttrp_g_n7_1" = "t7"."_ttrp_g_n7_1" AND "t3"."as_of_date" = "t7"."_ttrp_latest_n7") AS "t8" ON "t0"."item" = "t8"."item" AND "t0"."warehouse" = "t8"."warehouse") AS "t9"
            LEFT JOIN (SELECT "item", "warehouse", SUM("quantity") AS "sold", CAST(CAST(SUM("quantity") AS BIGINT) AS DECIMAL(19, 1)) / :demand_period AS "weekly_demand"
                FROM (SELECT "t11"."item", "t11"."warehouse", "t11"."lines", "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."quantity", "sales_line3"."unit_price", "sales_line3"."ext_sales_price", "sales_line3"."sold_date", "sales_line3"."customer", "sales_line3"."channel"
                        FROM (SELECT "item", "warehouse", COUNT("line_no") AS "lines"
                                FROM "sales_line"
                                WHERE "sold_date" >= :as_of_minus_demand_period_weeks AND "sold_date" <= :as_of
                                GROUP BY "item", "warehouse") AS "t11"
                            INNER JOIN "sales_line" AS "sales_line3" ON "t11"."item" = "sales_line3"."item" AND "t11"."warehouse" = "sales_line3"."warehouse") AS "t12"
                WHERE "t12"."sold_date" >= :as_of_minus_demand_period_weeks AND "t12"."sold_date" <= :as_of
                GROUP BY "item", "warehouse") AS "t15" ON "t9"."item" = "t15"."item" AND "t9"."warehouse" = "t15"."warehouse") AS "t16"
WHERE "t16"."on_hand" < :cover_target * "t16"."weekly_demand"
